<template x-if="mode.startsWith('day-') && form.items && sheet"><fieldset class="space-y-5" :disabled="!permission('can_edit_call_sheet') || dayLocked()" @input="touch()">
    <p x-show="dayLocked()" class="rounded-lg bg-amber-50 p-3 text-sm">Hari terkunci. Tutup editor dan gunakan tindakan Buka kunci untuk mengubahnya.</p>
    <div class="grid sm:grid-cols-3 gap-3"><label>Tanggal<input type="date" x-model="form.date" :aria-invalid="!!fields.date"></label><label>Jam mulai<input type="time" x-model="form.start" :aria-invalid="!!fields.start"></label><label>Lokasi hari<input x-model="form.location" list="mf-locations"></label><datalist id="mf-locations"><template x-for="location in sheet.locations || []" :key="location.id"><option :value="location.name"></option></template></datalist></div>
    <div class="space-y-3"><div class="flex justify-between items-center"><h3 class="font-semibold">Kegiatan berurutan</h3><button type="button" class="mf-btn" @click="addItem()">+ Kegiatan</button></div>
        <template x-for="(item,index) in form.items" :key="item.id"><div class="border rounded-xl p-3 space-y-3" draggable="true" @dragstart="dragIndex=index" @dragover.prevent @drop.prevent="dropped(index)">
            <div class="flex gap-2 items-center"><span class="mf-muted" x-text="index + 1"></span><button type="button" class="mf-btn" :disabled="index === 0" @click="moveItem(index,-1)" aria-label="Pindahkan kegiatan ke atas">↑</button><button type="button" class="mf-btn" :disabled="index === form.items.length - 1" @click="moveItem(index,1)" aria-label="Pindahkan kegiatan ke bawah">↓</button><button type="button" class="mf-btn ml-auto text-red-700" @click="form.items.splice(index,1);touch()">Hapus kegiatan</button></div>
            <div class="grid sm:grid-cols-3 gap-3"><label>Jenis<select x-model="item.kind" @change="touch()"><template x-for="kind in sheet.options.activity_kinds" :key="kind"><option :value="kind" x-text="kind.replaceAll('_',' ')"></option></template></select></label><label class="sm:col-span-2">Judul<input x-model="item.title" maxlength="500" :aria-invalid="!!fields['items.' + index + '.title']"></label><label>Durasi (menit)<input type="number" min="0" max="1440" step="1" x-model.number="item.duration" :aria-invalid="!!fields['items.' + index + '.duration']"></label><label>Scene<select x-model="item.scene_id" :disabled="!sheet.permissions.can_choose_scenes" @change="touch()"><option :value="null">Tanpa scene</option><template x-for="scene in sheet.scenes || []" :key="scene.id"><option :value="scene.id" x-text="scene.number + ' · ' + scene.heading"></option></template></select></label><label>DAY / NIGHT<select x-model="item.day_night" @change="touch()"><option value="">Ikuti scene</option><option>DAY</option><option>NIGHT</option></select></label></div>
            <details><summary class="text-sm cursor-pointer">Shot, sinopsis & catatan</summary><div class="grid sm:grid-cols-2 gap-3 mt-3"><label class="sm:col-span-2">Shot (pilih beberapa)<select multiple :disabled="!sheet.permissions.can_choose_shots" :value="item.shot_ids || []" @change="item.shot_ids=Array.from($event.target.selectedOptions).map(option=>option.value);touch()"><template x-for="shot in (sheet.shots || []).filter(shot => !item.scene_id || shot.scene === (sheet.scenes || []).find(scene=>scene.id===item.scene_id)?.number)" :key="shot.id"><option :value="shot.id" :selected="(item.shot_ids || []).includes(shot.id)" x-text="[shot.scene,shot.shot,shot.description].filter(Boolean).join(' · ')"></option></template></select></label><label>Override sinopsis<textarea rows="2" maxlength="3000" :value="item.synopsis_override || ''" @input="item.synopsis_override=$event.target.value"></textarea></label><label>Remarks<textarea rows="2" maxlength="2000" :value="item.remarks || ''" @input="item.remarks=$event.target.value"></textarea></label><label class="sm:col-span-2">Alasan pengulangan<input :value="item.repeat_reason || ''" maxlength="1000" @input="item.repeat_reason=$event.target.value"></label></div></details>
        </div></template>
        <p x-show="!form.items.length" class="mf-muted">Tambahkan kegiatan agar preview call sheet tersedia.</p>
    </div>
    <details open><summary class="font-semibold cursor-pointer">Detail call sheet</summary><div class="grid sm:grid-cols-2 gap-3 mt-3">
        <template x-for="key in ['title','location','address','parking','hospital']" :key="key"><label x-show="sheetField(key)"><span x-text="({title:'Judul call sheet',location:'Nama lokasi',address:'Alamat',parking:'Parkir',hospital:'Rumah sakit'})[key]"></span><input :value="form.call_sheet?.[key] || ''" @input="setSheetField(key,$event.target.value)" maxlength="500"></label></template>
        <label class="sm:col-span-2" x-show="sheetField('notes')">Catatan<textarea rows="3" maxlength="20000" :value="form.call_sheet?.notes || ''" @input="setSheetField('notes',$event.target.value)"></textarea></label><label class="sm:col-span-2" x-show="sheetField('set_rules')">Aturan set<textarea rows="2" maxlength="5000" :value="form.call_sheet?.set_rules || ''" @input="setSheetField('set_rules',$event.target.value)"></textarea></label>
    </div></details>
    <details><summary class="font-semibold cursor-pointer">Kru harian & HOD</summary><div class="space-y-3 mt-3"><p class="mf-muted">Pilih penugasan kru aktif. Pemeran mengikuti hubungan karakter pada scene.</p><div class="grid sm:grid-cols-2 gap-2"><template x-for="contact in (sheet.contacts || []).filter(c=>c.assignment_kind !== 'talent')" :key="contact.id"><label class="flex gap-2"><input type="checkbox" :checked="crewSelected(contact.id)" @change="toggleCrew(contact.id,$event.target.checked)"><span x-text="contact.name + ' · ' + contact.role"></span></label></template></div>
        <div x-show="sheetField('hod_entries')" class="space-y-2"><button type="button" class="mf-btn" @click="form.call_sheet ||= {}; form.call_sheet.hod_entries ||= []; form.call_sheet.hod_entries.push({role:'',name:''});touch()">+ HOD</button><template x-for="(entry,index) in form.call_sheet?.hod_entries || []" :key="index"><div class="grid grid-cols-2 gap-2"><label>Jabatan<input list="mf-hod-roles" x-model="entry.role" maxlength="80"></label><label>Nama<input x-model="entry.name" maxlength="500"></label><button type="button" class="mf-btn" @click="form.call_sheet.hod_entries.splice(index,1);touch()">Hapus HOD</button></div></template><datalist id="mf-hod-roles"><template x-for="role in sheet.options.hod_roles" :key="role"><option :value="role"></option></template></datalist></div>
        <div class="grid sm:grid-cols-2 gap-3"><template x-for="(name,key) in form.call_sheet?.hod || {}" :key="key"><label><span x-text="key.replaceAll('_',' ')"></span><input x-model="form.call_sheet.hod[key]"></label></template></div>
    </div></details>
    <details><summary class="font-semibold cursor-pointer">Cuaca & waktu penting</summary><div class="grid sm:grid-cols-3 gap-3 mt-3">
        <template x-for="period in ['morning','midday','night']" :key="period"><label><span x-text="({morning:'Pagi',midday:'Siang',night:'Malam'})[period]"></span><select :value="form.call_sheet?.weather_periods?.[period] || ''" @change="setWeather(period,$event.target.value)"><option value="">Belum diisi</option><template x-for="weather in sheet.options.weather" :key="weather"><option :value="weather" x-text="weather.replaceAll('_',' ')"></option></template></select></label></template>
        <template x-for="key in ['temperature_c','temperature_high_c','temperature_low_c']" :key="key"><label x-show="sheetField(key)"><span x-text="({temperature_c:'Suhu °C',temperature_high_c:'Suhu tertinggi °C',temperature_low_c:'Suhu terendah °C'})[key]"></span><input type="number" min="-50" max="60" step="any" :value="form.call_sheet?.[key] ?? ''" @input="setSheetField(key,$event.target.value === '' ? null : Number($event.target.value))"></label></template>
        <template x-for="key in ['sunrise','sunset','production_call','hod_call','breakfast','lunch','dinner']" :key="key"><label x-show="sheetField(key)"><span x-text="({sunrise:'Sunrise',sunset:'Sunset',production_call:'Production call',hod_call:'HOD call',breakfast:'Sarapan',lunch:'Makan siang',dinner:'Makan malam'})[key]"></span><input type="time" :value="form.call_sheet?.[key] || ''" @input="setSheetField(key,$event.target.value)"></label></template>
        <div class="sm:col-span-3 space-y-2"><button type="button" class="mf-btn" @click="form.call_sheet ||= {};form.call_sheet.important_times ||= [];form.call_sheet.important_times.push({label:'',time:''});touch()">+ Waktu penting</button><template x-for="(time,index) in form.call_sheet?.important_times || []" :key="index"><div class="grid sm:grid-cols-3 gap-2"><label>Kegiatan<input x-model="time.label" list="mf-important-times" maxlength="80"></label><label>Jam<input type="time" x-model="time.time"></label><button type="button" class="mf-btn self-end" @click="form.call_sheet.important_times.splice(index,1);touch()">Hapus</button></div></template><datalist id="mf-important-times"><template x-for="label in sheet.options.important_times" :key="label"><option :value="label"></option></template></datalist></div>
    </div></details>
</fieldset></template>
